mapper.select:
SELECT s.id, s.school_name AS name, s.school_code AS code, 1 AS type, s.province, s.city, s.district, s.address, s.contact_phone AS phone, s.contact_person AS contact_name, s.contact_phone, s.logo, s.status, 0 AS sort, '' AS remark, s.create_time, (SELECT COUNT(1) FROM grade g WHERE g.school_id = s.id AND g.deleted = 0) AS grade_count, (SELECT COUNT(1) FROM teacher t WHERE t.school_id = s.id AND t.deleted = 0) AS teacher_count, (SELECT COUNT(1) FROM student st WHERE st.school_id = s.id AND st.deleted = 0) AS student_count FROM school s WHERE s.deleted = 0
AND s.school_name LIKE CONCAT('%', #{query.name}, '%')
AND s.school_code = #{query.code}
AND s.province = #{query.province}
AND s.city = #{query.city}
AND s.status = #{query.status}
ORDER BY s.create_time DESC

SELECT id, school_name AS name, school_code AS code, 0 AS sort, '' AS remark FROM school WHERE deleted = 0
AND status = #{status}
ORDER BY create_time DESC
